import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Placeholder Reference","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/placeholders.md","filePath":"en/modules/corelib/placeholders.md","lastUpdated":0}`),a={name:`en/modules/corelib/placeholders.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="placeholder-reference" tabindex="-1">Placeholder Reference <a class="header-anchor" href="#placeholder-reference" aria-label="Permalink to “Placeholder Reference”">​</a></h1><p>CoreLib does not register a PlaceholderAPI expansion itself, but it provides the action context variable system used by all modules during action execution.</p><h2 id="action-context-variables" tabindex="-1">Action Context Variables <a class="header-anchor" href="#action-context-variables" aria-label="Permalink to “Action Context Variables”">​</a></h2><p>When an action is triggered, CoreLib automatically injects the following built-in variables into the context. All module action configs can reference them using the <code>%variable%</code> format.</p><h3 id="built-in-variables" tabindex="-1">Built-in Variables <a class="header-anchor" href="#built-in-variables" aria-label="Permalink to “Built-in Variables”">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>%player%</code></td><td>Player name.</td><td><code>Steve</code></td></tr><tr><td><code>%player_name%</code></td><td>Player name (same value as <code>%player%</code>).</td><td><code>Steve</code></td></tr><tr><td><code>%player_uuid%</code></td><td>Player UUID.</td><td><code>550e8400-e29b-...</code></td></tr><tr><td><code>%player_world%</code></td><td>World the player is in.</td><td><code>world</code></td></tr><tr><td><code>%player_x%</code></td><td>Player X coordinate (floating point).</td><td><code>128.5</code></td></tr><tr><td><code>%player_y%</code></td><td>Player Y coordinate (floating point).</td><td><code>64.0</code></td></tr><tr><td><code>%player_z%</code></td><td>Player Z coordinate (floating point).</td><td><code>256.0</code></td></tr><tr><td><code>%phase%</code></td><td>Current action phase.</td><td><code>success</code></td></tr></tbody></table><p>These player variables are only injected when the action context has a player. Variable name lookup is case-insensitive, and a value explicitly supplied by the caller takes precedence.</p><h3 id="usage-example" tabindex="-1">Usage Example <a class="header-anchor" href="#usage-example" aria-label="Permalink to “Usage Example”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_message text=&quot;&lt;green&gt;Congratulations %player_name%, operation successful!&lt;/green&gt;&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;run_command_as_console command=&quot;say %player_name% completed an operation in %player_world%&quot;&#39;</span></span></code></pre></div><h2 id="inline-tokens" tabindex="-1">Inline Tokens <a class="header-anchor" href="#inline-tokens" aria-label="Permalink to “Inline Tokens”">​</a></h2><p>CoreLib also supports the <code>&lt;show_item&gt;</code> inline token. When <code>show_item</code> is set in the action context, it renders an item hover tooltip in chat messages.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_message text=&quot;You received &lt;show_item&gt;!&quot;&#39;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Sub-modules (Forge, Gem, Skills, etc.) inject additional variables into their own action contexts. See each module&#39;s placeholder docs for details.</li><li>Action context variables and PlaceholderAPI placeholders are two independent systems. They share the same format but are resolved at different times.</li><li>PlaceholderAPI placeholders can also be used in actions (requires PlaceholderAPI installed).</li></ul>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};